'use strict';
const riskState={loaded:false,snapshots:[],rate:.60,selected:'live',message:'',undo:null};
const RISK_STORAGE='npl-risk-map-v09';
const RISK_STATUS={both_pass:'База і стрес проходять',stress_fails:'Стрес не проходить',base_fails:'База не проходить'};
let riskObserver;
function riskDemoSnapshots(){
  const groups=Object.fromEntries(Object.keys(NPL.SEGMENTS).map(k=>[k,demo.loans.filter(x=>x.segment===k)]));
  const defs=[['Банк · рання прострочка',groups.bank_early.slice(0,150),.58],['Банк · змішаний',groups.bank_early.slice(150).concat(groups.bank_late.slice(0,150)),.78],['Банк · тривала прострочка',groups.bank_late.slice(150),1.06],['МФО · рання прострочка',groups.mfo_early.slice(0,150),.62],['МФО · змішаний',groups.mfo_early.slice(150).concat(groups.mfo_late.slice(0,150)),.91],['МФО · тривала прострочка',groups.mfo_late.slice(150),1.10]];
  return defs.map(([name,loans,bid],i)=>{
    const share=loans.length/demo.loans.length,o=structuredClone(demo.meta.defaults);
    for(const k of ['startup','monthly_fixed','monthly_it','monthly_overhead'])o[k]*=share;
    o.extra_costs=o.extra_costs.map(c=>({...c,amount:c.amount*share}));
    const probe=NPL.evaluate(loans,o);o.price=Math.max(1000,probe.max_price*bid);
    return RISK.snapshot(loans,o,{id:'demo-'+(i+1),name,source:'synthetic',created_at:'2026-10-30T00:00:00Z'},NPL.evaluate);
  });
}
function riskInit(){
  if(riskState.loaded)return;
  riskState.loaded=true;riskState.snapshots=[];
  try{const saved=localStorage.getItem(RISK_STORAGE);if(saved){const p=RISK.validateCollection(JSON.parse(saved));riskState.snapshots=p.snapshots;riskState.rate=p.annual_return;}}
  catch(err){riskState.message='Збережену карту не прочитано: '+err.message+' Показано демо; попередній запис не перезаписано.';}
}
function riskLive(){return RISK.snapshot(rows,options,{id:'live',name:portfolioName+' · '+(project.source==='ml'?'ML12':'Сценарій36'),source:imported?'csv':'synthetic',created_at:new Date().toISOString()},NPL.evaluate);}
function riskItems(){return [riskLive(),...riskState.snapshots];}
function riskCollection(){return RISK.validateCollection({schema:RISK.SCHEMA,policy:RISK.POLICY,annual_return:riskState.rate,snapshots:riskState.snapshots});}
function riskPersist(){
  try{localStorage.setItem(RISK_STORAGE,JSON.stringify(riskCollection()));riskState.message='Карту збережено у цьому браузері. Реєстри договорів не зберігаються.';}
  catch(err){riskState.message='Збереження у браузері недоступне. Поточна карта лишається в пам’яті; експортуйте JSON.';}
}
function riskClass(m){return m.status==='both_pass'?'risk-pass':m.status==='stress_fails'?'risk-caution':'risk-fail';}
function riskSaveCurrent(){
  riskInit();if(riskState.snapshots.length>=RISK.LIMIT)throw Error('Досягнуто ліміт '+RISK.LIMIT+' знімків.');
  const s=riskLive(),name=$('#risk-save-name')?.value.trim()||portfolioName+' · оцінка '+(riskState.snapshots.filter(x=>!x.id.startsWith('demo-')).length+1);
  do{s.id='saved-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,12);}while(riskState.snapshots.some(x=>x.id===s.id));s.name=name;
  const checked=RISK.validateSnapshot(s);error('');riskState.snapshots.push(checked);riskState.selected=checked.id;riskPersist();switchTab('risk');toast('Поточну оцінку збережено окремим знімком.');
}
function renderRiskMap(){
  riskInit();let items;
  try{items=riskItems();}catch(err){$('#tab-risk').innerHTML=`<div class="notice">Карту не побудовано: ${esc(err.message)} <button class="text-button" data-goto="overview">Перевірити поточні параметри →</button></div>`;return;}
  const metrics=items.map(s=>RISK.measure(s,riskState.rate)),selected=items.find(s=>s.id===riskState.selected)||items[0];riskState.selected=selected.id;
  const plotted=metrics.filter(m=>m.plottable).length;
  $('#tab-risk').innerHTML=`<div class="risk-intro"><p><b>Порівняння сценарних оцінок.</b> Праворуч — сильніше падіння NPV під заданим стресом. Вище — більша базова IRR. Це не ймовірність збитку.</p><span class="chip">${plotted} точок · ${items.length} оцінок</span></div><div class="panel risk-toolbar"><div><label for="risk-rate">Спільна ставка дисконту, % річних</label><div class="risk-rate-controls"><input id="risk-rate" type="number" min="0" max="150" step="5" value="${riskState.rate*100}" aria-label="Спільна ставка дисконту, відсотки"><button class="button secondary" data-risk-action="rate">Застосувати</button></div><small class="risk-applied-rate">У розрахунках: ${pct(riskState.rate)}</small></div><div class="risk-save"><label for="risk-save-name">Назва знімка поточної оцінки</label><div><input id="risk-save-name" type="text" maxlength="120" placeholder="Наприклад: Банк А · пропозиція 1"><button class="button primary" data-risk-action="save">＋ Зберегти поточну</button></div></div><div class="risk-export"><button class="button secondary" data-risk-action="json">↓ Знімки JSON</button><button class="button secondary" data-risk-action="csv">↓ CSV</button><button class="button secondary" data-risk-action="import">↑ Додати JSON</button></div></div><p class="risk-storage" role="status">${esc(riskState.message||'Шість прикладів синтетичні. Знімки зберігаються у цьому браузері; первинні реєстри не копіюються. JSON експортує збережені знімки, CSV — усі видимі оцінки.')}${riskState.undo?' <button class="text-button" data-risk-action="undo">Скасувати вилучення</button>':''}</p><div class="risk-layout"><div class="panel risk-chart-panel"><div class="panel-heading"><div><h2>Дохідність і чутливість до стресу</h2><p>Площа круга пропорційна піковій потребі у фінансуванні бази</p></div></div><div class="risk-legend"><span><i class="risk-pass"></i>База і стрес ≥ 0 NPV</span><span><i class="risk-caution"></i>Лише база ≥ 0 NPV</span><span><i class="risk-fail"></i>База &lt; 0 NPV</span></div><div id="risk-plot" class="risk-plot"></div><p class="fine">Пунктир — спільна цільова дохідність. Номер точки відповідає рядку таблиці. Оцінки без однозначної IRR показано у таблиці без точки. Однакові точки можуть перекриватися — оберіть рядок у таблиці.</p></div><aside class="panel risk-detail" id="risk-detail"></aside></div><div class="panel table-panel risk-table-panel"><div class="panel-heading"><div><h2>Оцінки портфелів</h2><p>Натисніть назву або точку, щоб розкрити склад розрахунку. Поточна оцінка змінюється разом із параметрами; знімки зафіксовано.</p></div></div><div class="table-wrap"><table><thead><tr><th>№ / Портфель</th><th class="num">IRR, річна</th><th class="num">Падіння NPV / вкладення</th><th class="num">Базовий NPV</th><th class="num">Стресовий NPV</th><th class="num">Піковий капітал</th><th>Статус</th></tr></thead><tbody>${metrics.map((m,i)=>`<tr class="${m.id===selected.id?'risk-selected-row':''}"><td><button class="text-button" data-risk-select="${esc(m.id)}">${i+1}. ${esc(m.name)}</button><small>${m.source==='synthetic'?'Синтетичні дані':m.source==='csv'?'Імпорт CSV · сценарна модель':'Імпортований знімок · без перевірки реєстру'}</small></td><td class="num">${pct(m.base.irr)}</td><td class="num">${num(m.risk_pct,1)}%</td><td class="num ${m.base.npv>=0?'positive-text':'negative-text'}">${signed(m.base.npv)}</td><td class="num ${m.stress.npv>=0?'positive-text':'negative-text'}">${signed(m.stress.npv)}</td><td class="num">${money(m.base.funding_peak)}</td><td><span class="risk-status ${riskClass(m)}">${RISK_STATUS[m.status]}</span>${!m.plottable?'<small>Без точки: IRR не визначена</small>':''}</td></tr>`).join('')}</tbody></table></div></div><details class="panel risk-method"><summary>Формула, стрес-сценарій та межі порівняння</summary><div class="risk-method-body"><div class="formula">X = (NPV бази − NPV стресу) / (ціна покупки + початкові витрати) × 100%</div><p>Стрес відносно кожної бази: множник частки платників × 0,80; множник усіх майбутніх витрат × 1,25; затримка +3 міс. Початкова ціна та витрати в момент 0 не змінюються. Сума від платника незмінна. Регулярні витрати подовжуються за правилами фінансового движка. Це окремий відносний тест; вкладка «Сценарії» показує свої опорні сценарії.</p><p>NPV всіх оцінок перераховується за спільною ставкою ${pct(riskState.rate)}. Потоки в кінці місяця, умовна купівля в момент 0. Різні строки збережено, потоки не обрізаються. Податки та залучене фінансування не включено.</p><p>IRR обчислюється з базового потоку за одним переходом знака. За повторних відтоків або відсутності кореня оцінка не має точки. Низька чутливість сама по собі не означає безпечну покупку; статус NPV та якість даних показуються окремо. Від’ємний X означає поліпшення NPV у заданому стресі й потребує перевірки структури витрат.</p><p>Шість демопортфелів — непересічні частини початкового синтетичного реєстру, із заданими цінами та пропорційно виділеними спільними витратами. Поточна оцінка може включати ті самі вимоги: карта порівнює альтернативи, їхні результати не підсумовуються. Це не оптимізація покупок під бюджет і не емпірична оцінка ризику України.</p><p>Знімки містять лише агреговані місячні потоки, назву та припущення. Первинні реєстри, історії ML і плани стратегії до них не входять. Імпорт JSON додає знімки; ставка поточної карти зберігається. Ліміт ${RISK.LIMIT} знімків, JSON до 2 МБ.</p></div></details>`;
  renderRiskDetail(selected);drawRiskPlot();updateSource();
  if(riskObserver)riskObserver.disconnect();riskObserver=new ResizeObserver(()=>{if(active==='risk')drawRiskPlot();});riskObserver.observe($('#risk-plot'));
}
function renderRiskDetail(s){
  const m=RISK.measure(s,riskState.rate),a=s.assumptions;
  $('#risk-detail').innerHTML=`<div class="eyebrow">${s.id==='live'?'ПОТОЧНИЙ РОЗРАХУНОК':'ЗАФІКСОВАНИЙ ЗНІМОК'}</div><h2>${esc(s.name)}</h2><span class="risk-status ${riskClass(m)}">${RISK_STATUS[m.status]}</span><div class="risk-coordinate"><span>Падіння NPV / початкові вкладення</span><strong>${num(m.risk_pct,1)}%</strong><small>${signed(m.base.npv)} → ${signed(m.stress.npv)}</small></div><dl><div><dt>Базова IRR, річна</dt><dd>${pct(m.base.irr)}</dd></div><div><dt>Ціна покупки</dt><dd>${money(s.price)}</dd></div><div><dt>Початкові витрати</dt><dd>${money(s.startup)}</dd></div><div><dt>Знаменник X</dt><dd>${money(m.initial)}</dd></div><div><dt>Падіння NPV, грн</dt><dd>${money(m.decline)}</dd></div><div><dt>Всі витрати бази*</dt><dd>${money(m.base.future_cost+s.startup)}</dd></div><div><dt>Піковий капітал бази</dt><dd>${money(m.base.funding_peak)}</dd></div><div><dt>Окупність бази</dt><dd>${m.base.payback===null?'Не досягається':num(m.base.payback,1)+' міс.'}</dd></div><div><dt>Горизонт: база / стрес</dt><dd>${m.base.horizon} / ${m.stress.horizon} міс.</dd></div><div><dt>Договорів / на перевірці</dt><dd>${num(s.count)} / ${num(s.review_count)}</dd></div></dl><p class="fine">* З початковими, без ціни покупки. Окупність недисконтована. ${s.review_count?'Частина вимог не має прогнозних зборів до перевірки.':''}</p><p class="fine">База: платники ${num(a.payer_multiplier*100)}% опорних; сума від платника ${num(a.multiplier*100)}%; витрати ${num(a.expense_multiplier*100)}%; затримка ${a.delay} міс.</p>${!m.plottable?`<div class="notice">${m.base.irr_status==='nonconventional'?'Повторні відтоки: однозначна IRR не припускається.':'Однозначної IRR немає.'} Оцінка не розміщується на карті.</div>`:''}${m.risk_pct<0?'<div class="notice">Стрес поліпшив NPV. Перевірте співвідношення зборів і витрат.</div>':''}<div class="download-links">${s.id==='live'?'<button class="button secondary" data-goto="montecarlo">Моделювати Монте-Карло →</button><button class="text-button" data-goto="overview">Відкрити поточну оцінку →</button>':`<button class="button secondary" data-risk-remove="${esc(s.id)}">Прибрати з карти</button>`}</div><p class="fine">${s.id!=='live'?'Для Монте-Карло завантажте первинний реєстр цього знімка як поточний портфель. ':''}Знімок: ${esc(s.created_at.slice(0,10))}. ${s.source==='imported'?'Потоки імпортовані; первинний реєстр не перевірено.':'Сценарні припущення потребують калібрування.'}</p>`;
}
function drawRiskPlot(){
  const host=$('#risk-plot');if(!host)return;
  const items=riskItems(),points=items.map((s,i)=>({...RISK.measure(s,riskState.rate),index:i+1})).filter(m=>m.plottable);
  if(!points.length){host.innerHTML='<div class="empty">Немає оцінок з однозначною IRR. Дивіться NPV та пояснення в таблиці.</div>';return;}
  const w=Math.max(300,Math.floor(host.clientWidth)),h=w<470?320:390,p={l:59,r:23,t:31,b:65},maxR=w<470?24:32;
  let xmin=Math.min(0,...points.map(m=>m.risk_pct)),xmax=Math.max(1,...points.map(m=>m.risk_pct));
  let ymin=Math.min(0,...points.map(m=>m.base.irr*100)),ymax=Math.max(1,riskState.rate*100,...points.map(m=>m.base.irr*100));
  const dx=(xmax-xmin)*.13,dy=(ymax-ymin)*.15;xmin=xmin<0?xmin-dx:0;xmax+=dx;ymin=ymin<0?ymin-dy:0;ymax+=dy;
  const x=v=>p.l+maxR+(v-xmin)/(xmax-xmin)*(w-p.l-p.r-maxR*2),y=v=>h-p.b-maxR-(v-ymin)/(ymax-ymin)*(h-p.t-p.b-maxR*2);
  const maxCapital=Math.max(...points.map(m=>m.base.funding_peak));
  let svg=`<svg class="risk-scatter" viewBox="0 0 ${w} ${h}" role="group" aria-label="Карта: X — падіння NPV у стресі відносно початкових вкладень, Y — базова IRR. Точки доступні клавіатурою."><text class="risk-axis-label" x="${p.l}" y="16">Базова IRR, % річних</text>`;
  for(let i=0;i<=4;i++){const value=ymin+(ymax-ymin)*i/4,yy=y(value);svg+=`<line x1="${p.l}" x2="${w-p.r}" y1="${yy}" y2="${yy}" class="risk-grid"/><text x="${p.l-9}" y="${yy+4}" text-anchor="end">${num(value,0)}</text>`;}
  const ticks=w<470?3:4;for(let i=0;i<=ticks;i++){const value=xmin+(xmax-xmin)*i/ticks,xx=x(value);svg+=`<line x1="${xx}" x2="${xx}" y1="${p.t}" y2="${h-p.b}" class="risk-grid"/><text x="${xx}" y="${h-p.b+21}" text-anchor="middle">${num(value,0)}%</text>`;}
  svg+=`<line x1="${p.l}" x2="${w-p.r}" y1="${y(riskState.rate*100)}" y2="${y(riskState.rate*100)}" class="risk-hurdle"/><text x="${w-p.r}" y="${h-20}" text-anchor="end" class="risk-axis-label">Падіння NPV / початкові вкладення, % →</text>`;
  points.sort((a,b)=>a.id===riskState.selected?1:b.id===riskState.selected?-1:b.base.funding_peak-a.base.funding_peak).forEach(m=>{
    const radius=maxR*Math.sqrt(m.base.funding_peak/maxCapital),cx=x(m.risk_pct),cy=y(m.base.irr*100),selected=m.id===riskState.selected;
    svg+=`<g class="risk-point ${riskClass(m)} ${selected?'is-selected':''}" tabindex="0" role="button" aria-pressed="${selected}" aria-label="${esc(m.name)}: IRR ${num(m.base.irr*100,1)}%, падіння NPV ${num(m.risk_pct,1)}%" data-risk-select="${esc(m.id)}"><title>${esc(m.name)} · IRR ${num(m.base.irr*100,1)}% · Падіння NPV ${num(m.risk_pct,1)}% · Капітал ${money(m.base.funding_peak)}</title><circle class="risk-hit" cx="${cx}" cy="${cy}" r="${Math.max(21,radius)}"/><circle class="risk-bubble" cx="${cx}" cy="${cy}" r="${radius}"/><text x="${cx}" y="${radius<12?cy-radius-7:cy+4}" text-anchor="middle">${m.index}</text></g>`;
  });
  host.innerHTML=svg+'</svg>';
}
function riskMemo(){riskInit();const items=riskItems();return `<article class="memo"><div class="memo-label">КАРТА РИЗИК — ДОХІДНІСТЬ · СЦЕНАРНІ ОЦІНКИ</div><h2>Порівняння портфелів</h2><p>X = (NPV бази − NPV стресу) / (ціна + початкові витрати) × 100%. Ставка для всіх NPV: ${pct(riskState.rate)}. Це не ймовірність збитку.</p><p>Відносний стрес: 80% базової частки платників, 125% майбутніх витрат, затримка +3 міс.; ціна та початкові витрати незмінні. Y — IRR базового потоку, розмір точки — піковий капітал бази. До податків, без залученого фінансування.</p><table><thead><tr><th>Оцінка</th><th>IRR</th><th>Падіння NPV</th><th>NPV бази / стресу</th></tr></thead><tbody>${items.map(s=>{const m=RISK.measure(s,riskState.rate);return `<tr><td>${esc(s.name)}</td><td>${pct(m.base.irr)}</td><td>${num(m.risk_pct,1)}%</td><td>${signed(m.base.npv)} / ${signed(m.stress.npv)}</td></tr>`;}).join('')}</tbody></table><p>Синтетичні або імпортовані сценарні оцінки. Результати альтернатив не підсумовуються; первинні реєстри знімків не зберігаються. Оцінки без однозначної IRR лишаються у таблиці. Порівняння не визначає оптимальний набір покупок.</p></article>`;}
document.addEventListener('click',e=>{
  const select=e.target.closest('[data-risk-select]');if(select&&active==='risk'){riskState.selected=select.dataset.riskSelect;const s=riskItems().find(x=>x.id===riskState.selected);if(s){renderRiskDetail(s);drawRiskPlot();document.querySelectorAll('.risk-table-panel tbody tr').forEach(tr=>tr.classList.toggle('risk-selected-row',tr.querySelector('[data-risk-select]')?.dataset.riskSelect===s.id));}return;}
  const remove=e.target.closest('[data-risk-remove]');if(remove){const index=riskState.snapshots.findIndex(s=>s.id===remove.dataset.riskRemove);if(index>=0){riskState.undo={index,item:riskState.snapshots[index]};riskState.snapshots.splice(index,1);riskState.selected='live';riskPersist();renderRiskMap();}return;}
  const action=e.target.closest('[data-risk-action]')?.dataset.riskAction;if(!action)return;
  try{
    if(action==='save')riskSaveCurrent();
    if(action==='rate'){const field=$('#risk-rate');if(field.value==='')throw Error('Вкажіть ставку.');const rate=Number(field.value)/100;RISK.cashSummary({gross:[0],costs:[0]},1,rate);riskState.rate=rate;riskPersist();error('');renderRiskMap();}
    if(action==='json'){download('npl-risk-map.json',JSON.stringify(riskCollection(),null,2),'application/json;charset=utf-8');toast('Експортовано збережені знімки; поточний розрахунок спершу збережіть.');}
    if(action==='csv')download('npl-risk-map.csv',RISK.csv(riskItems(),riskState.rate),'text/csv;charset=utf-8');
    if(action==='import')$('#risk-input').click();
    if(action==='undo'&&riskState.undo){if(riskState.snapshots.length>=RISK.LIMIT)throw Error('Немає місця для відновлення.');riskState.snapshots.splice(riskState.undo.index,0,riskState.undo.item);riskState.undo=null;riskPersist();renderRiskMap();}
  }catch(err){error('Карта: '+err.message);}
});
document.addEventListener('keydown',e=>{const point=e.target.closest('.risk-point');if(point&&['Enter',' '].includes(e.key)){e.preventDefault();point.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
document.addEventListener('change',async e=>{
  if(e.target.id!=='risk-input')return;const file=e.target.files[0];if(!file)return;
  try{
    riskInit();if(file.size>2*1024*1024)throw Error('JSON перевищує 2 МБ.');
    const p=RISK.validateCollection(JSON.parse(await file.text()),{imported:true}),next=[...riskState.snapshots];
    for(const s of p.snapshots){const old=next.find(x=>x.id===s.id);if(old){const same=x=>JSON.stringify({...x,source:'imported'});if(same(old)!==same(s))throw Error('ID вже існує з іншими даними: '+s.id);}else next.push(s);}
    if(next.length>RISK.LIMIT)throw Error('Після імпорту понад '+RISK.LIMIT+' знімків.');
    const added=next.length-riskState.snapshots.length;riskState.snapshots=next;riskState.selected=p.snapshots[0]?.id||'live';riskPersist();error('');renderRiskMap();toast('Додано '+added+' знімків. Спільну ставку поточної карти збережено.');
  }catch(err){error('Імпорт карти не виконано: '+err.message);}finally{e.target.value='';}
});
